        (
            (0 4 7 3)
            (1 2 6 5)
            (0 1 5 4)
            (3 7 6 2)
            (0 3 2 1)
            (4 5 6 7)
        );
    }
);
""")

w("system/snappyHexMeshDict", HDR + """
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      snappyHexMeshDict;
}
castellatedMesh true;
snap            true;
addLayers       false;

geometry
{
    inlet           { type triSurfaceMesh; file "inlet.stl"; }
    outlet          { type triSurfaceMesh; file "outlet.stl"; }
    duct_walls      { type triSurfaceMesh; file "duct_walls.stl"; }
    honeycomb_walls { type triSurfaceMesh; file "honeycomb_walls.stl"; }
}

castellatedMeshControls
{
    maxLocalCells       5000000;
    maxGlobalCells      10000000;
    minRefinementCells  10;
    nCellsBetweenLevels 2;

    features    ();

    refinementSurfaces
    {
        honeycomb_walls { level (1 1); }
        duct_walls      { level (0 0); }
        inlet           { level (0 0); }
        outlet          { level (0 0); }
    }

    resolveFeatureAngle 30;

    refinementRegions   {}

    locationInMesh      (0 0 -0.02);

    allowFreeStandingZoneFaces true;
}

snapControls
{
    nSmoothPatch    3;
    tolerance       2.0;
    nSolveIter      30;
    nRelaxIter      5;
    nFeatureSnapIter 10;
    implicitFeatureSnap true;
    explicitFeatureSnap false;
    multiRegionFeatureSnap false;
}

addLayersControls
{
    relativeSizes   true;
    layers          {}
    expansionRatio  1.0;
    finalLayerThickness 0.3;
    minThickness    0.1;
    nGrow           0;
    featureAngle    60;
    nRelaxIter      3;
    nSmoothSurfaceNormals 1;
    nSmoothNormals  3;
    nSmoothThickness 10;
    maxFaceThicknessRatio 0.5;
    maxThicknessToMedialRatio 0.3;
    minMedialAxisAngle 90;
    nBufferCellsNoExtrude 0;
    nLayerIter      50;
}

meshQualityControls
{
    maxNonOrtho         65;
    maxBoundarySkewness 20;
    maxInternalSkewness 4;
    maxConcave          80;
    minVol              1e-13;
    minTetQuality       1e-15;
    minArea             -1;
    minTwist            0.02;
    minDeterminant      0.001;
    minFaceWeight       0.05;
    minVolRatio         0.01;
    minTriangleTwist    -1;
    nSmoothScale        4;
    errorReduction      0.75;
}

mergeTolerance 1e-6;
""")

for cmd in (["blockMesh"], ["snappyHexMesh", "-overwrite"]):
    r = subprocess.run(cmd, capture_output=True, text=True)
    print(" ".join(cmd), "-> rc", r.returncode)
    print("\n".join((r.stdout + r.stderr).splitlines()[-12:]))

w("system/fvSchemes", HDR + """
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSchemes;
}
ddtSchemes      { default steadyState; }
gradSchemes     { default Gauss linear; }
divSchemes      { default none; }
laplacianSchemes { default Gauss linear corrected; }
interpolationSchemes { default linear; }
snGradSchemes   { default corrected; }
""")

w("system/fvSolution", HDR + """
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    object      fvSolution;
}
solvers {}
PIMPLE {}
""")

r = subprocess.run(["snappyHexMesh", "-overwrite"], capture_output=True, text=True)
print("rc", r.returncode)
print("\n".join((r.stdout + r.stderr).splitlines()[-25:]))

